{
  "tasks": [
    {
      "task_id": "T01",
      "title": "按项目汇总已完成任务工时总和（排除丙项目）",
      "business_question": "在不包含丙项目的情况下，各项目已完成任务的工时总和是多少？",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标“按项目汇总已完成任务的工时总和”，并严格遵循排除丙项目和仅统计已完成任务的约束。删除此任务将无法获得任何相关分析结果。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              },
              {
                "field": "field_0002",
                "operator": "ne",
                "value": "丙"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_work_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
